import pandas as pd
import re
import os

random.seed(42)

# Load data
train_df = pd.read_csv("./input/ru_train.csv")
test_df = pd.read_csv("./input/ru_test_2.csv")
sample_sub = pd.read_csv("./input/ru_sample_submission_2.csv")

# Build frequency-based mapping: before -> most common after
mapping = {}
for _, row in train_df.iterrows():
    before = str(row["before"])
    after = str(row["after"])
    mapping.setdefault(before, {}).setdefault(after, 0)
    mapping[before][after] += 1

final_mapping = {k: max(v.items(), key=lambda x: x[1])[0] for k, v in mapping.items()}

# Precompute common delimiters and punctuation
DELIMITERS = re.compile(r"([_\-\.\,\:\;\!\?\s]+)")
PUNCT = set(".,-!?;:()[]{}")


def normalize_token(before):
    # Safe conversion to string
    before = str(before) if before is not None else ""

    # Direct lookup
    if before in final_mapping:
        return final_mapping[before]

    # Try lowercase
    lower = before.lower()
    if lower in final_mapping:
        return final_mapping[lower]

    # Try to split on delimiters and reassemble (recursive backoff for compound tokens)
    parts = DELIMITERS.split(before)
    if len(parts) > 1:
        normalized_parts = []
        for part in parts:
            if part in DELIMITERS.pattern:
                normalized_parts.append(part)
            else:
                # Recursive call (with caching, but recursion depth is small)
                normalized_parts.append(normalize_token(part))
        return "".join(normalized_parts).strip()

    # Special handling for transliteration
    if before.endswith("_trans"):
        parts = before.replace("_trans", " _trans").split()
        res = []
        for p in parts:
            if p == "_trans":
                res.append("_trans")
            elif p in final_mapping:
                res.append(final_mapping[p])
            elif p.lower() in final_mapping:
                res.append(final_mapping[p.lower()])
            else:
                res.append(p)
        return " ".join(res).replace(" _trans", "_trans").strip()

    # Punctuation: return as-is if single char
    if len(before) == 1 and before in PUNCT:
        return before

    # Numbers: return as-is if pure digits (but we could do more, but this is atomic and safe)
    if before.isdigit():
        return before

    # Last resort: return original
    return before


# Prepare test set: construct 'id' column
test_df["id"] = (
    test_df["sentence_id"].astype(str) + "_" + test_df["token_id"].astype(str)
)

# Predict test set
predictions = [normalize_token(x) for x in test_df["before"].tolist()]
submission = pd.DataFrame({"id": test_df["id"], "after": predictions})
os.makedirs("./submission", exist_ok=True)
submission.to_csv("./submission/submission.csv", index=False)

# Validation: hold-out 50k from training
train_sample = train_df.sample(n=50000, random_state=42)
correct = sum(
    1
    for _, row in train_sample.iterrows()
    if normalize_token(str(row["before"])) == str(row["after"])
)
accuracy = correct / len(train_sample)
print(f"Hold-out validation accuracy: {accuracy:.6f}")
